//! Opens the damaged fixtures (tests/corpus/damaged, generated by
//! scripts/make-fixtures.mjs) through the public API: each is repaired as its
//! manifest says (ADR-0004), and refused when opened strictly.
#![allow(
    clippy::expect_used,
    clippy::panic,
    reason = "test helpers: a failed expectation is a test failure"
)]

use std::path::PathBuf;

use pdf_syntax::{
    Budget, CancellationToken, Capability, Error, IndirectValue, MalformedKind, MemorySource,
    Object, ObjectId, OpenOptions, PdfFile, RepairReport, RepairTrailer, ResourceLimits, XrefEntry,
};

fn budget() -> Budget {
    Budget::new(ResourceLimits::default(), CancellationToken::new())
}

fn open_with(name: &str, options: OpenOptions) -> Result<PdfFile<MemorySource>, Error> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/corpus/damaged")
        .join(name);
    let bytes = std::fs::read(path).expect("fixture present");
    let source = MemorySource::from_vec(bytes, &ResourceLimits::default())?;
    PdfFile::open_with(source, options, &mut budget())
}

fn open(name: &str) -> PdfFile<MemorySource> {
    open_with(name, OpenOptions::default()).expect("repaired")
}

fn id(number: u32) -> ObjectId {
    ObjectId {
        number,
        generation: 0,
    }
}

fn resolve(file: &PdfFile<MemorySource>, number: u32) -> IndirectValue {
    file.resolve(id(number), &mut budget()).expect("resolvable")
}

fn catalog_type(file: &PdfFile<MemorySource>) -> Option<Object> {
    let root = file.root().expect("root");
    match file.resolve(root, &mut budget()).expect("root resolves") {
        IndirectValue::Object(Object::Dictionary(catalog)) => catalog.get(b"Type").cloned(),
        _ => None,
    }
}

fn strict_kind(name: &str) -> Option<MalformedKind> {
    match open_with(name, OpenOptions::strict()) {
        Err(Error::Malformed { kind, .. }) => Some(kind),
        Err(Error::Truncated { .. }) => None,
        other => panic!("{name}: strict opening gave {other:?}"),
    }
}

fn cause_kind(report: &RepairReport) -> Option<MalformedKind> {
    match report.cause {
        Error::Malformed { kind, .. } => Some(kind),
        _ => None,
    }
}

fn numbers(file: &PdfFile<MemorySource>) -> Vec<u32> {
    file.entries().map(|(number, _)| number).collect()
}

#[test]
fn files_repaired_from_a_trailer_found_by_the_scan() {
    for (name, kind) in [
        ("no-startxref.pdf", MalformedKind::MissingStartxref),
        ("wrong-startxref.pdf", MalformedKind::MissingXref),
    ] {
        assert_eq!(strict_kind(name), Some(kind), "{name}");
        let file = open(name);
        let report = file.repair().expect("repaired");
        assert_eq!(cause_kind(&report), Some(kind), "{name}");
        assert_eq!(
            (report.objects, report.conflicts, report.trailer),
            (5, 0, RepairTrailer::Found),
            "{name}"
        );
        assert_eq!(file.root(), Some(id(1)));
        assert_eq!(catalog_type(&file), Some(Object::Name(b"Catalog".to_vec())));
    }
}

#[test]
fn objects_past_their_entries_are_found_on_lookup() {
    let strict = open_with("shifted-objects.pdf", OpenOptions::strict()).expect("opens");
    assert!(matches!(
        strict.resolve(id(1), &mut budget()),
        Err(Error::Malformed {
            kind: MalformedKind::ObjectIdMismatch,
            ..
        })
    ));
    let file = open("shifted-objects.pdf");
    assert_eq!(file.repair(), None);
    assert_eq!(catalog_type(&file), Some(Object::Name(b"Catalog".to_vec())));
    let report = file.repair().expect("repaired on lookup");
    assert_eq!(report.trailer, RepairTrailer::Original);
    assert_eq!(cause_kind(&report), Some(MalformedKind::ObjectIdMismatch));
}

#[test]
fn files_without_a_trailer_use_their_catalog() {
    for (name, objects) in [("truncated.pdf", 5), ("no-trailer.pdf", 5)] {
        assert_eq!(
            strict_kind(name),
            Some(MalformedKind::MissingStartxref),
            "{name}"
        );
        let file = open(name);
        let report = file.repair().expect("repaired");
        assert_eq!(
            (report.objects, report.trailer),
            (objects, RepairTrailer::Catalog),
            "{name}"
        );
        assert_eq!(file.root(), Some(id(1)), "{name}");
    }
    // The header of the cut object survived: it is indexed, but unreadable.
    let file = open("truncated.pdf");
    assert_eq!(numbers(&file), [1, 2, 3, 4, 5]);
    assert!(matches!(
        file.resolve(id(5), &mut budget()),
        Err(Error::Truncated { .. } | Error::Malformed { .. })
    ));
}

#[test]
fn the_newest_occurrence_of_an_object_wins() {
    assert_eq!(
        strict_kind("duplicate-object.pdf"),
        Some(MalformedKind::MissingEof)
    );
    let file = open("duplicate-object.pdf");
    assert_eq!(file.repair().expect("repaired").conflicts, 1);
    let IndirectValue::Stream(stream) = resolve(&file, 4) else {
        panic!("object 4 is the content stream");
    };
    let data = file.stream_data(&stream).expect("in bounds");
    let text = String::from_utf8_lossy(&data);
    assert!(text.contains("CastlePDF updated revision"), "{text}");
}

#[test]
fn headers_in_stream_data_are_not_objects() {
    let file = open("header-in-stream.pdf");
    assert_eq!(numbers(&file), [1, 2, 3, 4, 5, 6, 7]);
    assert_eq!(file.repair().expect("repaired").conflicts, 0);
}

#[test]
fn object_streams_found_by_the_scan_are_read() {
    assert_eq!(
        strict_kind("objstm-unindexed.pdf"),
        Some(MalformedKind::MissingXref)
    );
    let file = open("objstm-unindexed.pdf");
    let report = file.repair().expect("repaired");
    assert_eq!(report.trailer, RepairTrailer::Found);
    for number in [1, 2, 5] {
        assert!(
            matches!(
                file.entry(number),
                Some(XrefEntry::Compressed { stream: 6, .. })
            ),
            "object {number}"
        );
    }
    assert_eq!(catalog_type(&file), Some(Object::Name(b"Catalog".to_vec())));
}

#[test]
fn encrypted_files_are_never_repaired() {
    for name in ["encrypted.pdf", "encrypted-truncated.pdf"] {
        assert_eq!(
            open_with(name, OpenOptions::default()).err(),
            Some(Error::Unsupported(Capability::Encryption)),
            "{name}"
        );
    }
}
